import android.graphics.*;import android.opengl.*;import android.view.Surface;import java.nio.*;import java.nio.file.Files;import java.nio.file.Path;import maclauncher.android.bridge.*;import maclauncher.android.framework.*;
/** Real offscreen producer/consumer contexts and Canvas through original Android APIs. */
public final class NativeSurfaceTextureProbe {
 static void check(boolean okay,String message){if(!okay)throw new AssertionError(message+" EGL="+Integer.toHexString(EGL14.eglGetError())+" GL="+Integer.toHexString(GLES20.glGetError()));}
 static int shader(int kind,String source){int value=GLES20.glCreateShader(kind);GLES20.glShaderSource(value,source);GLES20.glCompileShader(value);int[] status={0};GLES20.glGetShaderiv(value,GLES20.GL_COMPILE_STATUS,status,0);check(status[0]!=0,GLES20.glGetShaderInfoLog(value));return value;}
 static void draw(int program,int channel){
  GLES20.glUseProgram(program);FloatBuffer vertices=ByteBuffer.allocateDirect(8*4).order(ByteOrder.nativeOrder()).asFloatBuffer();vertices.put(new float[]{-1,-1,1,-1,-1,1,1,1}).flip();int location=GLES20.glGetAttribLocation(program,"position");GLES20.glEnableVertexAttribArray(location);GLES20.glVertexAttribPointer(location,2,GLES20.GL_FLOAT,false,0,vertices);GLES20.glDrawArrays(GLES20.GL_TRIANGLE_STRIP,0,4);
  ByteBuffer pixel=ByteBuffer.allocateDirect(4);GLES20.glReadPixels(1,1,1,1,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,pixel);check((pixel.get(channel)&255)>240&&(pixel.get(3)&255)>240,"sample real external image channel "+channel);check(GLES20.glGetError()==0,"graphics state");
 }
 public static void main(String[] args)throws Exception{
  Path runtime=Path.of(args[0]),graphics=Path.of(args[1]),data=Path.of(args[2]);Files.createDirectories(data.resolve("files"));Files.createDirectories(data.resolve("cache"));HostFilesystem.configure(runtime,data,data.resolve("files"),data.resolve("cache"),"owned.surface.texture");
  System.setProperty("klepton.graphics",graphics.toString());System.load(runtime.resolve("native/libklepton-jvm.dylib").toString());System.load(runtime.resolve("native/libnativebinding.dylib").toString());JvmNativeMemory.configure(runtime.resolve("native/libandroid_runtime.dylib"));JvmNativeMemory.initialize();Graphics.configureHost(null,runtime.resolve("native/angle").toString(),8,8);NativeSurface.configureGraphics(graphics.toString());
  EGLDisplay display=EGL14.eglGetDisplay(0);check(EGL14.eglInitialize(display,new int[1],0,new int[1],0),"initialize");EGLConfig[] configs=new EGLConfig[1];check(EGL14.eglChooseConfig(display,new int[]{EGL14.EGL_RENDERABLE_TYPE,4,EGL14.EGL_SURFACE_TYPE,1,EGL14.EGL_RED_SIZE,8,EGL14.EGL_GREEN_SIZE,8,EGL14.EGL_BLUE_SIZE,8,EGL14.EGL_ALPHA_SIZE,8,EGL14.EGL_BIND_TO_TEXTURE_RGBA,1,EGL14.EGL_NONE},0,configs,0,1,new int[1],0),"config");
  EGLContext consumer=EGL14.eglCreateContext(display,configs[0],EGL14.EGL_NO_CONTEXT,new int[]{EGL14.EGL_CONTEXT_CLIENT_VERSION,2,EGL14.EGL_NONE},0),producer=EGL14.eglCreateContext(display,configs[0],EGL14.EGL_NO_CONTEXT,new int[]{EGL14.EGL_CONTEXT_CLIENT_VERSION,2,EGL14.EGL_NONE},0);
  EGLSurface output=EGL14.eglCreatePbufferSurface(display,configs[0],new int[]{EGL14.EGL_WIDTH,8,EGL14.EGL_HEIGHT,8,EGL14.EGL_NONE},0);check(EGL14.eglMakeCurrent(display,output,output,consumer),"consumer");int[] names={0};GLES20.glGenTextures(1,names,0);SurfaceTexture texture=new SurfaceTexture(names[0]);texture.setDefaultBufferSize(8,8);Surface surface=new Surface(texture);check(surface.isValid(),"original Surface retains producer");
  EGLSurface input=EGL14.eglCreateWindowSurface(display,configs[0],texture,new int[]{EGL14.EGL_NONE},0);check(!input.equals(EGL14.EGL_NO_SURFACE),"direct SurfaceTexture EGL producer");check(EGL14.eglMakeCurrent(display,input,input,producer),"producer");GLES20.glClearColor(0,0,1,1);GLES20.glClear(GLES20.GL_COLOR_BUFFER_BIT);long before=System.nanoTime();check(EGL14.eglSwapBuffers(display,input),"queue GPU frame");
  check(EGL14.eglMakeCurrent(display,output,output,consumer),"consumer return");texture.updateTexImage();check(texture.getTimestamp()>=before&&texture.getTimestamp()<=System.nanoTime(),"generated EGL frame timestamp uses Android uptime");float[] transform=new float[16];texture.getTransformMatrix(transform);check(transform[5]==-1&&transform[13]==1,"GL image origin transform");
  int vertex=shader(GLES20.GL_VERTEX_SHADER,"attribute vec2 position; varying vec2 uv; void main(){uv=position*0.5+0.5; gl_Position=vec4(position,0.,1.);}"),fragment=shader(GLES20.GL_FRAGMENT_SHADER,"#extension GL_OES_EGL_image_external : require\nprecision mediump float; varying vec2 uv; uniform samplerExternalOES source; void main(){gl_FragColor=texture2D(source,uv);}");int program=GLES20.glCreateProgram();GLES20.glAttachShader(program,vertex);GLES20.glAttachShader(program,fragment);GLES20.glLinkProgram(program);draw(program,2);
  check(EGL14.eglDestroySurface(display,input),"producer release");Canvas canvas=surface.lockCanvas(null);canvas.drawColor(Color.RED);surface.unlockCanvasAndPost(canvas);texture.updateTexImage();draw(program,0);check(texture.getDataSpace()==0x8810000,"Canvas sRGB data space");
  texture.detachFromGLContext();GLES20.glGenTextures(1,names,0);texture.attachToGLContext(names[0]);texture.updateTexImage();draw(program,0);texture.releaseTexImage();texture.release();check(texture.isReleased(),"released consumer");surface.release();HostSurfaceTexture.shutdown();check(NativeSurface.statistics()[0]==0,"all producer leases retired");
  GLES20.glDeleteProgram(program);GLES20.glDeleteShader(vertex);GLES20.glDeleteShader(fragment);GLES20.glDeleteTextures(1,names,0);EGL14.eglMakeCurrent(display,EGL14.EGL_NO_SURFACE,EGL14.EGL_NO_SURFACE,EGL14.EGL_NO_CONTEXT);EGL14.eglDestroySurface(display,output);EGL14.eglDestroyContext(display,producer);EGL14.eglDestroyContext(display,consumer);EGL14.eglTerminate(display);EGL14.eglReleaseThread();System.out.println("PASS raw SurfaceTexture GPU and Canvas producer pixels, cross-context external image, detach/attach and bounded retirement");
 }
}
